using System.IO;
using System.Net.Http;
using System.Net.Http.Json;
using System.Text;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using Microsoft.Data.Sqlite;
namespace VisionaryRouter.Desktop;
public sealed partial class RouterWindow {
 string lastSnapshot="", query=""; bool connected; int page; const int PageSize=12; readonly TextBlock pageLabel=Label(""); Button? previousPage,nextPage;

 static string Describe(JsonElement result){
 var lines=new List<string>();
 foreach(var property in result.EnumerateObject()){
 if(property.Name is "raw" or "device" or "routes" or "results")continue;
 var label=System.Text.RegularExpressions.Regex.Replace(property.Name,"([a-z])([A-Z])","$1 $2");
 label=char.ToUpperInvariant(label[0])+label[1..];
 if(property.Value.ValueKind==JsonValueKind.Null)continue;
 lines.Add(label+": "+(property.Value.ValueKind==JsonValueKind.True?"Yes":property.Value.ValueKind==JsonValueKind.False?"No":property.Value.ToString()));
 }
 return lines.Count>0?string.Join(Environment.NewLine,lines):"Operation completed.";
 }
 void SetPort(){var uri=new Uri($"http://localhost:{ReadPort()}");if(http.BaseAddress==uri)return;var auth=http.DefaultRequestHeaders.Authorization;http.Dispose();http=new HttpClient{BaseAddress=uri,Timeout=TimeSpan.FromMinutes(10)};http.DefaultRequestHeaders.Authorization=auth;}
 static int ReadPort(){foreach(var root in new[]{Environment.SpecialFolder.CommonApplicationData,Environment.SpecialFolder.LocalApplicationData}){var file=Path.Combine(Environment.GetFolderPath(root),"VisionaryRouter","router.db");if(!File.Exists(file))continue;try{using var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=file,Mode=SqliteOpenMode.ReadOnly}.ToString());db.Open();using var cmd=db.CreateCommand();cmd.CommandText="SELECT Value FROM Settings WHERE Key='ActiveWebPort'";if(int.TryParse(cmd.ExecuteScalar()?.ToString(),out var port)&&port>=1024&&port<=65535)return port;}catch(SqliteException){}}return 8088;}
 void Login(){var(w,p)=Dialog("Router sign in");p.Children.Add(Label("Administrator password"));var password=new PasswordBox();p.Children.Add(password);p.Children.Add(Button("Sign in",()=>{http.DefaultRequestHeaders.Authorization=new("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes("admin:"+password.Password)));w.Close();}));w.ShowDialog();}
 IEnumerable<Device> Filtered()=>devices.Where(d=>d.Enabled&&(d.Name.Contains(query,StringComparison.OrdinalIgnoreCase)||d.IpAddress.Contains(query,StringComparison.OrdinalIgnoreCase))).OrderBy(d=>d.SortOrder);
 IEnumerable<Device> VisibleDevices()=>Filtered().GroupBy(d=>d.Type).SelectMany(g=>g.Skip(page*PageSize).Take(PageSize));
 void UpdatePages(){var pages=Math.Max(1,(Filtered().GroupBy(d=>d.Type).Select(g=>g.Count()).DefaultIfEmpty(0).Max()+PageSize-1)/PageSize);page=Math.Clamp(page,0,pages-1);if(previousPage!=null)previousPage.IsEnabled=page>0;if(nextPage!=null)nextPage.IsEnabled=page<pages-1;pageLabel.Text=$"Page {page+1} / {pages} · {devices.Count} devices";}
 void AddSearch(StackPanel header){var row=new WrapPanel();header.Children.Add(row);row.Children.Add(Label("Search name / IP  "));var search=new TextBox{Width=220,Margin=new Thickness(0,4,12,4),Padding=new Thickness(6)};search.TextChanged+=(_,_)=>{query=search.Text;page=0;Render();};row.Children.Add(search);previousPage=Button("Previous",()=>{page=Math.Max(0,page-1);Render();});row.Children.Add(previousPage);pageLabel.Margin=new Thickness(4,10,12,4);row.Children.Add(pageLabel);nextPage=Button("Next",()=>{page++;Render();});row.Children.Add(nextPage);row.Children.Add(Button("Select filtered destinations",()=>{foreach(var d in Filtered().Where(d=>d.Type=="Decoder"))selected.Add(d.Id);Render();}));}
 (Window,StackPanel) Dialog(string title){var w=new Window{Owner=this,Title=title,Width=800,Height=650,MinWidth=500,MinHeight=400,Background=Background,WindowStartupLocation=WindowStartupLocation.CenterOwner};var p=new StackPanel{Margin=new Thickness(20)};w.Content=new ScrollViewer{Content=p,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};return(w,p);}
 async Task Run(Func<Task> action){if(busy)return;busy=true;Render();try{await action();}catch(Exception e){MessageBox.Show(this,e.Message,"Visionary Router",MessageBoxButton.OK,MessageBoxImage.Warning);}finally{busy=false;lastSnapshot="";await Refresh();}}
 static TextBox Field(StackPanel p,string label,string value=""){p.Children.Add(Label(label));var box=new TextBox{Text=value,Padding=new Thickness(6),Margin=new Thickness(0,0,0,8)};p.Children.Add(box);return box;}
 bool Confirm(string text)=>MessageBox.Show(this,text,"Visionary Router",MessageBoxButton.YesNo,MessageBoxImage.Question)==MessageBoxResult.Yes;
 async Task Send(HttpMethod method,string path,object? body=null){using var message=new HttpRequestMessage(method,path);if(body!=null)message.Content=JsonContent.Create(body);using var response=await http.SendAsync(message);if(!response.IsSuccessStatusCode)throw new Exception(await response.Content.ReadAsStringAsync());}
 void ManageDevices(){var(w,p)=Dialog("Devices & discovery");var search=Field(p,"Filter devices");var table=new DataGrid{Height=280,IsReadOnly=true,AutoGenerateColumns=false,EnableRowVirtualization=true,EnableColumnVirtualization=true,SelectionMode=DataGridSelectionMode.Single};foreach(var column in new[]{"Name","Type","IpAddress","OnlineState","Enabled"})table.Columns.Add(new DataGridTextColumn{Header=column=="IpAddress"?"IP address":column=="OnlineState"?"Status":column,Binding=new System.Windows.Data.Binding(column),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});void Reload()=>table.ItemsSource=devices.Where(d=>(d.Name+" "+d.IpAddress).Contains(search.Text,StringComparison.OrdinalIgnoreCase)).ToArray();search.TextChanged+=(_,_)=>Reload();p.Children.Add(table);Reload();var row=new WrapPanel();p.Children.Add(row);
 row.Children.Add(Button("Add",AddDevice));row.Children.Add(Button("Edit",()=>{if(table.SelectedItem is Device d)Edit(d);}));row.Children.Add(Button("Probe",async()=>{if(table.SelectedItem is Device d)await Run(async()=>{var result=await Post($"/api/devices/{d.Id}/probe",new{});MessageBox.Show(w,Describe(result),"Probe result");});Reload();}));row.Children.Add(Button("Identify",async()=>{if(table.SelectedItem is Device d)await Run(async()=>{var result=await Post($"/api/devices/{d.Id}/identify",new{});MessageBox.Show(w,result.ToString(),"Identify result");});}));
 row.Children.Add(Button("Remove",async()=>{if(table.SelectedItem is Device d&&Confirm($"Remove {d.Name} from the router?"))await Run(()=>Send(HttpMethod.Delete,$"/api/devices/{d.Id}"));Reload();}));
 row.Children.Add(Button("Clear decoder route",async()=>{if(table.SelectedItem is Device d&&d.Type=="Decoder"&&Confirm($"Stop video on {d.Name}?"))await Run(async()=>{var result=await Post($"/api/devices/{d.Id}/clear-route",new{});MessageBox.Show(w,result.ToString(),"Clear result");});}));
 foreach(var delta in new[]{-1,1}){var step=delta;row.Children.Add(Button(step<0?"Move up":"Move down",async()=>{if(table.SelectedItem is not Device d)return;await Run(async()=>{var items=devices.Where(x=>x.Type==d.Type).OrderBy(x=>x.SortOrder).ToList();int i=items.FindIndex(x=>x.Id==d.Id),j=i+step;if(j<0||j>=items.Count)return;(items[i],items[j])=(items[j],items[i]);await Send(HttpMethod.Post,"/api/devices/order",new{type=d.Type,deviceIds=items.Select(x=>x.Id).ToArray()});});Reload();}));}
 var subnet=Field(p,"Discover devices on subnet (example: 192.168.0.0/24)");p.Children.Add(Button("Scan & add",async()=>{await Run(async()=>{var result=await Post("/api/discovery/scan",new{subnet=subnet.Text});MessageBox.Show(w,result.ToString(),"Discovery results");});Reload();}));p.Children.Add(Button("Refresh list",async()=>{await Refresh();Reload();}));w.ShowDialog();}
 void Edit(Device d){var(w,p)=Dialog("Edit device");var name=Field(p,"Name",d.Name);var ip=Field(p,"IP address",d.IpAddress);var port=Field(p,"Control port",d.ControlPort.ToString());var type=new ComboBox{ItemsSource=new[]{"Encoder","Decoder"},SelectedItem=d.Type};p.Children.Add(Label("Type"));p.Children.Add(type);var enabled=new CheckBox{Content="Enabled",IsChecked=d.Enabled,Foreground=Brush("#FFFFFF"),Margin=new Thickness(0,12,0,12)};p.Children.Add(enabled);p.Children.Add(Label($"Model: {d.Model}\nFirmware: {d.Firmware}\nLast error: {d.LastError}"));p.Children.Add(Button("Save",async()=>await Run(async()=>{if(!int.TryParse(port.Text,out var n)||n<1||n>65535)throw new Exception("Control port must be 1–65535.");await Send(HttpMethod.Put,$"/api/devices/{d.Id}",new{name=name.Text,ipAddress=ip.Text,controlPort=n,type=type.SelectedItem,enabled=enabled.IsChecked==true});w.Close();})));w.ShowDialog();}
 sealed class Saved {public Guid Id{get;set;} public string Name{get;set;}="";public Guid[] DecoderIds{get;set;}=[];public override string ToString()=>Name;}
 async void SavedRoutes(){var(w,p)=Dialog("Groups & presets");var groups=new ListBox{Height=110};var presets=new ListBox{Height=110};async Task Reload(){groups.ItemsSource=await http.GetFromJsonAsync<List<Saved>>("/api/groups");presets.ItemsSource=await http.GetFromJsonAsync<List<Saved>>("/api/presets");}p.Children.Add(Label("Destination groups",20));p.Children.Add(groups);var name=Field(p,"Name for new group or preset");p.Children.Add(Button("Save selected destinations as group",async()=>await Run(async()=>{await Post("/api/groups",new{name=name.Text,decoderIds=selected.ToArray()});await Reload();})));p.Children.Add(Button("Select group",()=>{if(groups.SelectedItem is Saved g){selected.Clear();foreach(var id in g.DecoderIds.Where(id=>devices.Any(d=>d.Id==id&&d.Enabled)))selected.Add(id);Render();w.Close();}}));p.Children.Add(Button("Delete group",async()=>{if(groups.SelectedItem is Saved g&&Confirm($"Delete group {g.Name}?"))await Run(async()=>{await Send(HttpMethod.Delete,$"/api/groups/{g.Id}");await Reload();});}));p.Children.Add(Label("Routing presets",20));p.Children.Add(presets);p.Children.Add(Button("Save current live routes",async()=>await Run(async()=>{var routes=devices.Where(d=>d.Type=="Decoder"&&devices.Any(e=>e.Type=="Encoder"&&e.IpAddress==d.CurrentEncoderIp)).Select(d=>new{decoderId=d.Id,encoderId=devices.First(e=>e.Type=="Encoder"&&e.IpAddress==d.CurrentEncoderIp).Id}).ToArray();await Post("/api/presets",new{name=name.Text,routes});await Reload();})));p.Children.Add(Button("Recall preset",async()=>{if(presets.SelectedItem is Saved s&&Confirm($"Apply routes in {s.Name}?"))await Run(async()=>{var result=await Post($"/api/presets/{s.Id}/recall",new{});MessageBox.Show(w,result.ToString(),"Preset results");});}));p.Children.Add(Button("Delete preset",async()=>{if(presets.SelectedItem is Saved s&&Confirm($"Delete preset {s.Name}?"))await Run(async()=>{await Send(HttpMethod.Delete,$"/api/presets/{s.Id}");await Reload();});}));try{await Reload();w.ShowDialog();}catch(Exception e){MessageBox.Show(this,e.Message);}}
 async void Settings(){var(w,p)=Dialog("Settings & diagnostics");try{var info=await http.GetFromJsonAsync<JsonElement>("/api/system/status");p.Children.Add(Label($"Router version {info.GetProperty("version")}\nDevices: {info.GetProperty("deviceCount")} · Online: {info.GetProperty("onlineCount")}\nDatabase: {info.GetProperty("databasePath")}",16));var settings=await http.GetFromJsonAsync<JsonElement>("/api/network/settings");var port=Field(p,"Local service port (restart required)",settings.GetProperty("webPort").ToString());p.Children.Add(Label("Network adapters allowed to access the routing API"));var adapters=new List<(string,CheckBox)>();foreach(var nic in settings.GetProperty("interfaces").EnumerateArray()){var c=new CheckBox{Content=$"{nic.GetProperty("name")} · {nic.GetProperty("address")}",IsChecked=nic.GetProperty("selected").GetBoolean(),Foreground=Brush("#FFFFFF"),Margin=new Thickness(0,4,0,4)};p.Children.Add(c);adapters.Add((nic.GetProperty("id").GetString()!,c));}p.Children.Add(Label("New administrator password (blank keeps current password)"));var password=new PasswordBox{Padding=new Thickness(6)};p.Children.Add(password);p.Children.Add(Label("LAN access uses HTTP Basic authentication. Use only a trusted control network. Firewall rules are managed separately."));p.Children.Add(Button("Save network settings",async()=>await Run(async()=>{if(!int.TryParse(port.Text,out var n))throw new Exception("Enter a valid port.");await Post("/api/network/settings",new{webPort=n,interfaceIds=adapters.Where(x=>x.Item2.IsChecked==true).Select(x=>x.Item1).Distinct().ToArray(),newPassword=password.Password});MessageBox.Show(w,"Saved. Restart the routing engine to apply changes.");})));p.Children.Add(Button("Reconnect",async()=>await Run(async()=>{await Connect();})));p.Children.Add(Button("Restart engine",async()=>{if(owned is null){MessageBox.Show(w,"This engine was started separately. Close that instance and relaunch the desktop application to let it manage the engine.");return;}if(!Confirm("Restart the routing engine? Current hardware routes will stay as they are."))return;await Run(async()=>{owned.Kill(true);await owned.WaitForExitAsync();owned.Dispose();owned=null;await Connect();});}));p.Children.Add(Button("Clear ALL decoder routes",async()=>{if(Confirm("Stop video on ALL enabled decoders?"))await Run(async()=>{var result=await Post("/api/routes/clear",new{});MessageBox.Show(w,result.ToString(),"Clear results");});}));p.Children.Add(Label("Latest operation"));p.Children.Add(Label(status.Text));w.ShowDialog();}catch(Exception e){MessageBox.Show(this,e.Message,"Settings");}}
}
